```php
$stmt = $pdo->prepare("SELECT id, password_hash FROM users WHERE id = :id");
$stmt->execute(['id' => $user_id]);
$row = $stmt->fetch(PDO::FETCH_ASSOC);
echo password_verify($user_input, $row['password_hash']);
```

